import { Button, Card, Col, Row } from 'react-bootstrap';
import { Link, useLocation } from 'react-router-dom';
import { useEffect, useMemo, useState } from 'react';
import {
    emiCalculation,
    interestForMonth,
    principalRemaining,
    principalRepayment,
    annualToMonthlyInterestRate,
    numberWithCommas,
    formatDate,
    DateMonthYear,
    numberToRupeesWords,
} from './AllFunction';
import { getAddLoanDetailsRequest, resetGetAddLoanDetails, } from '../redux/actions';
import { usePageTitle, useRedux } from '../hooks';
import CompanyDetails from '../components/Atom/CompanyDetails';
import { callbackify } from 'util';

const LoanPdf = () => {

    usePageTitle({
        title: 'Loan',
        breadCrumbItems: [
            {
                path: '/loan/request',
                label: 'Loan',
            },
            {
                path: 'loan/pdf',
                label: 'Loan Pdf',
                active: true,
            },
        ],
    });

    const { dispatch, appSelector } = useRedux();
    const location = useLocation();
    const { loanDetails, loc } = location.state || false;

    const [loanState, setLoanState] = useState([]);
    const [state, setState] = useState({});

    useEffect(() => {
        setState(loanDetails);
    }, [loanDetails]);

    useEffect(() => {
        if (state?.loanAmount && state?.tenurePeriod && state?.interestRate) {
            calCulationTable();
        }
    }, [state?.loanAmount, state?.tenurePeriod, state?.interestRate, state?.dueDate]);


    // EMI table Calculation
    const calCulationTable = async () => {
        const initialDueDate = new Date(state?.dueDate || new Date());
        let remainingPrincipal = parseInt(state?.loanAmount || 0);

        const emi = emiCalculation(
            parseInt(state?.loanAmount || 0),
            parseInt(state?.interestRate || 0),
            parseFloat(state?.tenurePeriod || 0) / 12
        );

        setState((prev) => ({ ...prev, emiAmount: Math.ceil(emi) }));

        const newLoanData = [];

        for (let month = 1; month <= parseInt(state?.tenurePeriod || 0); month++) {
            const monthlyInterestRate = annualToMonthlyInterestRate(parseInt(state?.interestRate || 0));
            const monthInterestAmount = interestForMonth(remainingPrincipal, monthlyInterestRate);
            const principalRepay = principalRepayment(emi, monthInterestAmount);
            remainingPrincipal = principalRemaining(remainingPrincipal, principalRepay);
            if (remainingPrincipal < 0) remainingPrincipal = 0;

            const currentDueDate = new Date(initialDueDate);
            currentDueDate.setMonth(initialDueDate.getMonth() + month - 1);

            const monthFormatted = (currentDueDate.getMonth() + 1).toString().padStart(2, '0');
            const year = currentDueDate.getFullYear();
            const day = currentDueDate.getDate();
            const formattedDueDate = `${day.toString().padStart(2, '0')}/${monthFormatted}/${year}`;

            newLoanData.push({
                month,
                dueDate: formattedDueDate,
                principalRepayment: Math.round(principalRepay),
                interestForMonth: Math.round(monthInterestAmount),
                principalRepaymentAndInterest: Math.round(emi),
                principalRemain: Math.round(remainingPrincipal),
            });
        }

        // Update loanState once
        setLoanState(newLoanData);
    };


    const totalInterestAmount = useMemo(() => {
        const totalInterest = loanState.reduce((total, item) => {
            return total + (item.interestForMonth || 0);
        }, 0);
        return totalInterest;
    }, [loanState]);

    const totalPrincipalAmount = useMemo(() => {
        const totalPrincipalRepaymentAndInterest = loanState.reduce((total, item) => {
            return total + (item.principalRepaymentAndInterest || 0);
        }, 0);
        return totalPrincipalRepaymentAndInterest;
    }, [loanState]);

    // WelcomeDetails
    const WelcomeDetails = {
        toDate: formatDate(),
        status: state?.loanStatusName || '',
        loanNo: state?.loanNo || '',
        interestRate: state?.interestRate || '',
        loanAmount: `₹ ${numberWithCommas(state?.loanAmount || 0)}.00`,
        Tenure: `${state?.tenurePeriod || ''} (Months)`,
        emiAmount: `₹ ${numberWithCommas(state?.emiAmount || 0)}.00`,
        totalInterestAmount: `₹ ${numberWithCommas(totalInterestAmount || 0)}.00`,
        totalPrincipalAmount: `₹ ${numberWithCommas(totalPrincipalAmount || 0)}.00`,
        dateofAgreement: DateMonthYear(formatDate(state?.loanDate)),
        disbursedMethod: state?.disbursedMethodName || '',
        processFees: `₹ ${numberWithCommas(state?.processFees || 0)}.00`,
        headerSubDescripion: 'We Wish to list Loan details which are as follows: ',
    };
    const staffDetails = {
        staffCode: state?.staffCode,
        staffName: state?.staffName || '',
        departmentName: state?.departmentName || '',
        designationName: state?.designationName || '',
        address: state?.address || '',
        headerSubDescripion: 'We Wish to Staff details which are as follows: ',
    };

    return (
        <Row>
            <Col md={12}>
                <Row>
                    <Col className="d-flex justify-content-end">
                        <div>
                            <Link to={loc ? loc : '/loan/request'} >
                                <Button className='mb-2'>
                                    Back
                                    <span className="cursor-pointer ms-1">
                                        <i className={'fe-arrow-right'}></i>
                                    </span>
                                </Button>
                            </Link>

                        </div>
                    </Col>
                </Row>
                <Card>
                    <Card.Body>
                        <div className="panel-body">
                            <div className="d-flex justify-content-between align-items-center">
                                <div className="">
                                    <CompanyDetails fontSize="12px" imgSize="200px" borderBottom={false}
                                        styleObj={{
                                            display: 'flex',
                                            flexDirection: 'column',
                                            alignItems: 'start',
                                            justifyContent: 'start',
                                            textAlign: 'start',
                                            width: '100%',
                                            wordBreak: 'break-word'
                                        }}
                                    />
                                </div>
                                <div className="">
                                    <h4>
                                        Loan No #<strong>{WelcomeDetails.loanNo}</strong>
                                    </h4>
                                </div>
                            </div>
                            <hr />
                            <Row>
                                <Col md={6}>
                                    <div className="float-start mt-3">
                                        <address>
                                            {/* <p>{staffDetails.headerSubDescripion}</p> */}
                                            <table>
                                                <tr>
                                                    <th>Staff Code</th>
                                                    <td>: {staffDetails.staffCode}</td>
                                                </tr>
                                                <tr>
                                                    <th>Staff Name</th>
                                                    <td>: {staffDetails.staffName}</td>
                                                </tr>
                                                <tr>
                                                    <th>Department</th>
                                                    <td>: {staffDetails.departmentName}</td>
                                                </tr>
                                                <tr>
                                                    <th>Designation</th>
                                                    <td>: {staffDetails.designationName}</td>
                                                </tr>
                                                <tr>
                                                    <th style={{ "textAlign": 'top', "verticalAlign": "top" }}>Address</th>
                                                    <td style={{ "wordWrap": "break-word", "maxWidth": "300px" }}>: {staffDetails.address}</td>
                                                </tr>
                                            </table>
                                        </address>
                                    </div>
                                </Col>
                                <Col md={6}>
                                    <div className="float-end mt-3">
                                        <address>
                                            {/* <p>{WelcomeDetails.headerSubDescripion}</p> */}
                                            <table>
                                                <tr>
                                                    <th>Loan Amount</th>
                                                    <td>: {WelcomeDetails.loanAmount}</td>
                                                </tr>
                                                <tr>
                                                    <th>In word:</th>
                                                    <td>: {numberToRupeesWords(state?.loanAmount || 0)}</td>
                                                </tr>
                                                <tr>
                                                    <th>Loan Tenure</th>
                                                    <td>: {WelcomeDetails.Tenure}</td>
                                                </tr>
                                                <tr>
                                                    <th>Interest Rate</th>
                                                    <td>: {WelcomeDetails.interestRate}</td>
                                                </tr>
                                                <tr>
                                                    <th>EMI Amount</th>
                                                    <td>: {WelcomeDetails.emiAmount}</td>
                                                </tr>
                                                <tr>
                                                    <th>Interest Amount</th>
                                                    <td>: {WelcomeDetails.totalInterestAmount}</td>
                                                </tr>
                                                <tr>
                                                    <th>Process Fees</th>
                                                    <td>: {WelcomeDetails.processFees}</td>
                                                </tr>
                                                <tr>
                                                    <th>Total Payment</th>
                                                    <td>: {WelcomeDetails.totalPrincipalAmount}</td>
                                                </tr>
                                                <tr>
                                                    <th>Date of Agreement</th>
                                                    <td>: {WelcomeDetails.dateofAgreement}</td>
                                                </tr>
                                                <tr>
                                                    <th>Status</th>
                                                    <td>: {WelcomeDetails.status}</td>
                                                </tr>
                                            </table>
                                        </address>
                                    </div>
                                </Col>
                            </Row>

                            <Row>
                                <Col sm={12} className='d-flex justify-content-center'>
                                    <h4>Due Payment List</h4>
                                </Col>
                            </Row>

                            <Row>
                                <Col md={12}>
                                    <div className="table-responsive">
                                        <table className="table mt-4">
                                            <thead>
                                                <tr>
                                                    <th>#</th>
                                                    <th>Due Date</th>
                                                    <th>Amount</th>
                                                    <th>Principal</th>
                                                    <th>Interest</th>
                                                    <th>Future Principal</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {loanState.map((item, idx) => (
                                                    <tr key={idx}>
                                                        <td>{idx + 1}</td>
                                                        <td>{item.dueDate}</td>
                                                        <td>{`₹ ${numberWithCommas(
                                                            item.principalRepaymentAndInterest
                                                        )}`}</td>
                                                        <td>{`₹ ${numberWithCommas(item.principalRepayment)}`}</td>
                                                        <td>{`₹ ${numberWithCommas(item.interestForMonth)}`}</td>
                                                        <td>{`₹ ${numberWithCommas(item.principalRemain)}`}</td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
                                </Col>
                            </Row>
                            <Row>
                                <Col xl={6} xs={6}>
                                    <div className="clearfix mt-4">
                                        <h5 className="small text-dark fw-normal">PAYMENT TERMS AND POLICIES</h5>
                                        <small>
                                            This receipt has been automatically generated by our software system. It serves as a digital record of your transaction, ensuring accuracy and transparency. Please retain this receipt for your records, as it reflects the details processed by the software.
                                        </small>
                                    </div>
                                </Col>
                                <Col xs={6} xl={{ offset: 3, span: 3 }}>
                                    <hr />
                                    <div className="d-flex justify-content-between">
                                        <h3>Total : </h3>
                                        <h3 className="text-end">
                                            Rs. {numberWithCommas(parseInt(state?.loanAmount || 0))}
                                        </h3>
                                    </div>
                                </Col>
                            </Row>
                            <hr />
                            <div className="d-print-none">
                                <div className="float-end">
                                    <Link
                                        to="#"
                                        className="btn btn-dark waves-effect waves-light me-1"
                                        onClick={(e) => {
                                            window.print();
                                        }}>
                                        <i className="fa fa-print"></i>
                                    </Link>
                                </div>
                                <div className="clearfix"></div>
                            </div>
                        </div>
                    </Card.Body>
                </Card>
            </Col>
        </Row>
    );
};

export default LoanPdf;
